mapper.select:
SELECT s.id, s.student_no, s.name, s.gender, s.class_id, s.phone, s.address, s.create_time, c.class_name FROM student s LEFT JOIN class c ON s.class_id = c.id AND c.is_deleted = 0 WHERE s.is_deleted = 0
AND s.name LIKE CONCAT('%', #{name}, '%')
AND s.class_id = #{classId}
ORDER BY s.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM student s WHERE s.is_deleted = 0
AND s.name LIKE CONCAT('%', #{name}, '%')
AND s.class_id = #{classId}

SELECT COUNT(*) FROM student
WHERE student_no = #{studentNo} AND is_deleted = 0

    AND id != #{excludeId}
